theorem ordinalDerived_union [T1Space K] {A B : Set K}
    (hA : IsClosed A) (hB : IsClosed B) (α : Ordinal.{u}) :
    ordinalDerived (A ∪ B) α = ordinalDerived A α ∪ ordinalDerived B α
